{
  "recommendations": [
    {
      "target": "L1",
      "action": "Install a dedicated thermal relief valve on EA-425B shell side independent of HV-B-SIN and HV-B-SOUT, or add HV-B-SIN and HV-B-SOUT to the managed valve program locked open when EA-425B is in service.",
      "reason": "RV-PATH-EA425B is not credited because its inlet valves HV-B-SIN and HV-B-SOUT are closed, leaving the exchanger with no relief path during external fire. A local relief valve or managed open block valves removes the isolation that defeats the existing relief path."
    },
    {
      "target": "C1",
      "action": "Add an interlock on HV-QW-B-IN and HV-QW-B-OUT that prevents opening unless HV-B-SIN and HV-B-SOUT are both confirmed open.",
      "reason": "The scenario occurs when quench water valves open early per proc:P-REB-START-2 while shell-side block valves remain closed, isolating the relief path. An engineered interlock directly prevents the out-of-sequence operation that defeats RV-PATH-EA425B, preferred over procedure revision alone."
    },
    {
      "target": "C2",
      "action": "Install a check valve in line L-A-SOUT to prevent reverse flow from DA-406 into EA-425A when SV-421QA/QB fail to open.",
      "reason": "The gap arises because DA-406 overpressure pushes liquid/vapor back through L-A-SOUT into EA-425A when its relief valves fail. A check valve in L-A-SOUT directly blocks the backflow path, addressing the consequence independent of the fire cause or relief valve reliability."
    },
    {
      "target": "L2",
      "action": "Revise procedure P-REB-START-2 to add a mandatory hold point with independent verification that HV-B-SIN and HV-B-SOUT are open before opening HV-QW-B-IN/HV-QW-B-OUT, and install a local shell-side pressure alarm that activates if quench water flow starts while block valves are closed.",
      "reason": "This target has zero protection layers against the procedural error of opening quench water early. The procedure revision adds a procedural barrier with verification, and the pressure alarm provides an engineered detection layer that alerts operators to the hazardous condition before overpressure."
    },
    {
      "target": "L3",
      "action": "Lock open HV-A-SIN (or add it to the managed valve program with position monitoring) to match HV-A-SOUT which is already locked open.",
      "reason": "RV-PATH-EA425A is credited but only at pfd_if_isolatable because HV-A-SIN is unmanaged. Locking it open or managing its position ensures the relief path remains available during external fire, closing the gap without adding new equipment."
    }
  ]
}

